1041	+  final ApiClient _apiClient;
1042	+
1043	+  /// Sends exactly `{content, source}` — this story never passes
1044	+  /// `chatMessageId`/`occurredAt`/`mediaDurationSeconds` (Boundaries: no
1045	+  /// `Entry` field beyond the modeled 8; those three are optional in the
1046	+  /// contract and belong to later stories/epics).
1047	+  Future<Either<Failure, EntryDto>> create({
1048	+    required String content,
1049	+    required EntrySource source,
1050	+  }) async {
1051	+    final result = await _apiClient.post(
1052	+      'entries-create',
1053	+      data: {'content': content, 'source': source.name},
1054	+    );
